// Приводим запрос SendPulse к одному виду: кто написал и что написал
const b = $json.body || $json;
const pick = (...keys) => { for (const k of keys) { const v = k.split('.').reduce((o, p) => o && o[p], b); if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim(); } return ''; };
const contact_id = pick('contact_id', 'contact.id', 'contactId');
const text = pick('text', 'message', 'last_message', 'info.message.text', 'info.message');
const name = pick('name', 'full_name', 'contact.name', 'contact.full_name');
const channel = pick('channel') || 'instagram';
if (!contact_id || !text) throw new Error('Нет contact_id или text в запросе от SendPulse: ' + JSON.stringify(b).slice(0, 500));
return [{ json: { contact_id, text, name, channel } }];

// Отделяем служебные метки от текста для клиента
const raw = String($json.output || '').trim();
const leadLine = (raw.match(/^\[ЗАЯВКА\].*$/m) || [''])[0];
const needManager = /^\[МЕНЕДЖЕР\]/m.test(raw);
const reply = raw.replace(/^\[ЗАЯВКА\].*$/mg, '').replace(/^\[МЕНЕДЖЕР\].*$/mg, '').trim();
const fields = {};
leadLine.replace('[ЗАЯВКА]', '').split(';').forEach(p => { const [k, ...v] = p.split('='); if (k && k.trim()) fields[k.trim()] = v.join('=').trim(); });
const src = $('Данные из SendPulse').first().json;
return [{ json: { ...src, reply, isLead: !!leadLine, needManager, lead: fields, leadLine } }];
